Here is a complete, working example of a "Global Tooltip Manager" in NextJS.

### 1. The Setup
First, install `framer-motion`. It is the standard for smooth tooltips in React/NextJS because it handles animations and z-indexes elegantly.

```bash
npm install framer-motion
```

### 2. Create the Context Provider
We will create a system where:
1.  The **Context Provider** holds the state of the currently open tooltip.
2.  The **Tooltip Context** passes the `openTooltip` method down to individual Tooltip components.
3.  Any Tooltip can trigger the provider to update the state, which automatically closes any previously open tooltip.

#### `src/context/TooltipContext.tsx`

```tsx
'use client'; // NextJS requires client components for interactivity

import React, { createContext, useContext, useState, ReactNode, useRef, useEffect } from 'react';

type TooltipId = string;
type TooltipData = {
  content: ReactNode;
  id: TooltipId;
};

// 1. Define the shape of our Context
interface TooltipContextType {
  isOpen: boolean;
  activeId: TooltipId | null;
  data: TooltipData | null;
  openTooltip: (id: TooltipId, content: ReactNode) => void;
  closeTooltip: () => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [activeId, setActiveId] = useState<TooltipId | null>(null);
  const [data, setData] = useState<TooltipData | null>(null);

  // Function called by child tooltips to request being open
  const openTooltip = (id: TooltipId, content: ReactNode) => {
    // This logic effectively closes the previous tooltip by simply
    // setting a new state. If the ID is the same, it just resets.
    setActiveId(id);
    setData({ id, content });
  };

  const closeTooltip = () => {
    setActiveId(null);
    setData(null);
  };

  // Optional: Close on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      // You could add a ref check here to ensure we only close
      // if clicking on a specific wrapper div.
      if (activeId) {
        closeTooltip();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [activeId]);

  return (
    <TooltipContext.Provider
      value={{ isOpen: !!activeId, activeId, data, openTooltip, closeTooltip }}
    >
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (context === undefined) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

